using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
namespace BWVR {
// A bounded household layer; the three established adults retain their existing work and social controllers.
public sealed class VillageFamilies:MonoBehaviour {
 public FamilyState State=>season().Families;public int VisibleChildren=>children.Count;public bool Visiting=>first>=0;
 Func<SliceState> season;IslandNavigation nav;VillagerRoutine[] adults;readonly Dictionary<int,Vector3> homes=new Dictionary<int,Vector3>();readonly List<GameObject> children=new List<GameObject>();readonly List<IslandNavigator> walkers=new List<IslandNavigator>();
 Vector3[] originalHomes;bool firstJoined,secondJoined;int first=-1,second=-1,visitHome;float elapsed,shared;Material heartMaterial;GameObject heart;FamilyState displayed;
 public static VillageFamilies Build(Transform parent,IslandNavigation nav,VillagerRoutine[] adults,Func<SliceState> season){var go=new GameObject("Village households and children");go.transform.SetParent(parent,false);var family=go.AddComponent<VillageFamilies>();family.nav=nav;family.adults=adults;family.season=season;family.Initialize();return family;}
 void Initialize(){originalHomes=adults.Select(a=>a.GetComponent<CarryItem>().home).ToArray();foreach(var house in nav.GetComponentsInChildren<IslandPlacementView>().Where(h=>h.redesigned).OrderBy(h=>h.sourceLine)){for(int i=0;i<12;i++){var at=house.transform.position+Quaternion.Euler(0,i*30,0)*Vector3.forward*nav.Scale*12;if(nav.Sample(at,nav.villager,2,out var safe)){homes[house.sourceLine]=nav.ProjectFoot(safe,nav.villager);break;}}}
  heartMaterial=new Material(Shader.Find("BWVR/GameSurface")){color=new Color(.9f,.35f,.35f),enableInstancing=true};heart=new GameObject("Shared home bond");heart.transform.SetParent(transform,false);for(int i=0;i<3;i++){var part=GameObject.CreatePrimitive(i==2?PrimitiveType.Cube:PrimitiveType.Sphere);part.transform.SetParent(heart.transform,false);part.transform.localPosition=new Vector3(i==0?-.28f:i==1?.28f:0,i==2?-.25f:0,0);part.transform.localRotation=Quaternion.Euler(0,0,i==2?45:0);part.transform.localScale=new Vector3(.65f,.65f,.25f);part.GetComponent<Renderer>().sharedMaterial=heartMaterial;var col=part.GetComponent<Collider>();col.enabled=false;Destroy(col);}heart.transform.localScale=Vector3.one*nav.Scale;ResetWorld();}
 bool Free(int i){var a=adults[i];return !a.GetComponent<CarryItem>().held&&!a.GetComponent<VillagerResourceGathering>().Active&&!a.GetComponent<VillagerSocial>().Active&&!a.GetComponent<VillagerSocial>().RecentFright&&a.GetComponent<VillagerSocial>().Memory.injury<.4f&&!a.GetComponent<VillagerExploration>().Active&&!a.GetComponent<VillagerBlockPlay>().Active;}
 bool Scheduled(VillagerRoutine adult)=>displayed==State&&first>=0&&(adult==adults[first]||adult==adults[second]);
 public bool Owns(VillagerRoutine adult)=>Scheduled(adult)&&((adult==adults[first]&&firstJoined)||(adult==adults[second]&&secondJoined));
 public bool TickAdult(VillagerRoutine adult,float dt){if(!Scheduled(adult))return false;int index=Array.IndexOf(adults,adult);if(!Free(index)){if(Owns(adult))EndVisit();return false;}if(!Owns(adult)){adult.ResetTask();adult.GetComponent<IslandNavigator>().ResetRoute();}if(index==first)firstJoined=true;else secondJoined=true;var target=homes[visitHome]+Vector3.right*nav.Scale*(index==first?-2:2);var walker=adult.GetComponent<IslandNavigator>();if(walker.MoveTo(target,adult.transform.lossyScale.y*1.6f,dt))adult.GetComponent<HumanoidMotion>()?.LookAt(adults[index==first?second:first].transform);else if(walker.Blocked&&elapsed>8){EndVisit();return false;}return true;}
 public void Advance(float dt,bool paused){foreach(var child in children)child.GetComponent<HumanoidMotion>().paused=paused;if(paused||dt<=0||float.IsNaN(dt)||float.IsInfinity(dt))return;if(displayed!=State)ResetWorld();var s=State;s.clock=Mathf.Min(100000000,s.clock+dt);
  if(Visiting){elapsed+=dt;if(adults[first].GetComponent<CarryItem>().held||adults[second].GetComponent<CarryItem>().held){EndVisit();}else if(firstJoined&&secondJoined&&Vector3.Distance(adults[first].transform.position,adults[second].transform.position)<nav.Scale*6&&Vector3.Distance(adults[first].transform.position,homes[visitHome])<nav.Scale*5){float beforeShared=shared;shared+=dt;s.together=Mathf.Min(100000000,s.together+dt);var a=adults[first].GetComponent<VillagerSocial>();var b=adults[second].GetComponent<VillagerSocial>();bool safe=a.Memory.PeerWilling("villager-"+second,season().Hybrid.time)&&b.Memory.PeerWilling("villager-"+first,season().Hybrid.time);if(safe){s.bond=Mathf.Clamp01(s.bond+dt*.004f);a.Memory.RememberPeer("villager-"+second,true,season().Hybrid.time);b.Memory.RememberPeer("villager-"+first,true,season().Hybrid.time);if((int)(shared/5)!=(int)(beforeShared/5)){a.GetComponent<HumanoidMotion>()?.React();b.GetComponent<HumanoidMotion>()?.React();}if(!s.Partnered&&s.bond>=.65f&&s.together>=60){s.FormHousehold(first,second,visitHome);SetHomes();}}else{s.bond=Mathf.Clamp01(s.bond-dt*.02f);EndVisit();}if(shared>=25)EndVisit();}if(elapsed>180)EndVisit();
  }else if(s.clock>=s.visitAt){s.visitAt=s.clock+30;TryVisit();}
  if(s.Partnered&&homes.ContainsKey(s.home)&&s.TryBirth(season().Resources.wheat,season().Hybrid.seed)){season().Resources.wheat-=2;SyncChildren();adults[s.parentA].GetComponent<HumanoidMotion>()?.React();adults[s.parentB].GetComponent<HumanoidMotion>()?.React();}
  for(int i=0;i<s.children.Length;i++){var data=s.children[i];data.age=Mathf.Min(100000000,data.age+dt);var child=children[i];child.transform.localScale=Vector3.one*adults[data.parentA].transform.localScale.x*(.42f+.16f*data.traits.stature+Mathf.Min(.15f,data.age/6000));var home=homes.TryGetValue(data.home,out var h)?h:adults[data.parentA].transform.position;int cycle=Mathf.FloorToInt(s.clock/(12+data.traits.diligence*12));Vector3 target=home;if(cycle%3==0||data.traits.sociability>.7f)target=adults[cycle%2==0?data.parentA:data.parentB].transform.position;else {float angle=(cycle*137.5f+i*70)*Mathf.Deg2Rad;target+=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*nav.Scale*(3+data.traits.boldness*7);}if(nav.Sample(target,nav.villager,3,out var safe)){var before=child.transform.position;walkers[i].MoveTo(safe,nav.Scale*(1+data.traits.diligence),dt);var direction=child.transform.position-before;direction.y=0;if(direction.sqrMagnitude>1e-12f)child.transform.rotation=Quaternion.LookRotation(direction);}}
  heart.SetActive(s.Partnered||Visiting);if(heart.activeSelf&&homes.TryGetValue(s.Partnered?s.home:visitHome,out var place))heart.transform.position=place+Vector3.up*nav.Scale*(5+Mathf.Sin(s.clock)*.15f);
 }
 public void Release(VillagerRoutine adult){if(Scheduled(adult))EndVisit();}
 bool TryVisit(){if((!season().developmentFocus&&!season().Finished&&season().water<45)||homes.Count==0||season().Resources.wheat<3||season().Resources.NeedsStorage)return false;int a=-1,b=-1;float score=-1;for(int i=0;i<3;i++)for(int j=i+1;j<3;j++){if(State.courtA>=0&&(i!=State.courtA||j!=State.courtB))continue;if((!Free(i)&&!Free(j))||adults[i].GetComponent<CarryItem>().held||adults[j].GetComponent<CarryItem>().held)continue;var x=adults[i].GetComponent<VillagerSocial>().Memory;var y=adults[j].GetComponent<VillagerSocial>().Memory;if(!x.PeerWilling("villager-"+j,season().Hybrid.time)||!y.PeerWilling("villager-"+i,season().Hybrid.time))continue;float value=x.PeerAppeal("villager-"+j)+y.PeerAppeal("villager-"+i);if(value>score){score=value;a=i;b=j;}}if(a<0)return false;int home=State.Partnered?State.home:homes.OrderBy(h=>Vector3.Distance(h.Value,adults[a].transform.position)+Vector3.Distance(h.Value,adults[b].transform.position)).First().Key;if(!homes.ContainsKey(home))return false;var discoveries=nav.GetComponentInChildren<IslandDiscoveries>();if(!discoveries.Reachable(adults[a].transform.position,homes[home],nav.villager)||!discoveries.Reachable(adults[b].transform.position,homes[home],nav.villager))return false;State.courtA=a;State.courtB=b;first=a;second=b;firstJoined=secondJoined=false;visitHome=home;elapsed=shared=0;return true;}
 void EndVisit(){bool owned=first>=0;if(first>=0)foreach(int i in new[]{first,second}){if((i==first&&!firstJoined)||(i==second&&!secondJoined))continue;adults[i].GetComponent<HumanoidMotion>()?.LookAt(null);adults[i].GetComponent<IslandNavigator>().ResetRoute();adults[i].ResetTask();}first=second=-1;firstJoined=secondJoined=false;if(owned&&displayed==State)State.visitAt=State.clock+65;}
 void SetHomes(){if(State.Partnered&&homes.TryGetValue(State.home,out var home))foreach(int i in new[]{State.parentA,State.parentB})adults[i].GetComponent<CarryItem>().home=home+Vector3.right*nav.Scale*(i==State.parentA?-2:2);}
 void SyncChildren(){while(children.Count<State.children.Length){int i=children.Count;var data=State.children[i];var prefab=Resources.Load<GameObject>("Villagers/Villager"+(data.parentA%3));if(prefab==null)throw new InvalidOperationException("Missing villager art for child");var child=Instantiate(prefab,transform);child.name="Village child "+data.id;child.transform.position=homes.TryGetValue(data.home,out var at)?at:adults[data.parentA].transform.position;var walker=child.AddComponent<IslandNavigator>();walker.Initialize(nav,false);children.Add(child);walkers.Add(walker);}}
 public void ResetWorld(){EndVisit();foreach(var child in children)Destroy(child);children.Clear();walkers.Clear();displayed=State;for(int i=0;i<3;i++)adults[i].GetComponent<CarryItem>().home=originalHomes[i];SetHomes();SyncChildren();heart?.SetActive(State.Partnered);}
 void OnDestroy(){if(heartMaterial!=null)Destroy(heartMaterial);}
}
}
